import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.vLhlLNVn.js";const r="/assets/compilednewdevice.BWBzbX3x.png",s="/assets/tasmota_main.A0vlOJ4H.png",o="/assets/tasmota_ota.BjYXOMGu.png",d="/assets/tasmota_upload.dMabUQna.png",l="/assets/espeasy_ota.DyrQ82D1.png",b=JSON.parse('{"title":"Tasmota / ESPEasy migrieren","description":"","frontmatter":{"order":6},"headers":[],"relativePath":"de/adapter/esphome/migration.md","filePath":"de/adapter/esphome/migration.md","lastUpdated":1794650433000}'),c={name:"de/adapter/esphome/migration.md"};function h(m,e,p,u,g,S){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="tasmota-espeasy-migrieren" tabindex="-1">Tasmota / ESPEasy migrieren <a class="header-anchor" href="#tasmota-espeasy-migrieren" aria-label="Permalink to &quot;Tasmota / ESPEasy migrieren&quot;">​</a></h1><p>Die Migration von früheren Sonoff Tasmota- oder ESPEasy-Setups ist sehr einfach. Sie müssen lediglich eine Binärdatei von ESPHome erstellen lassen und diese dann im Webinterface hochladen.</p><h2 id="download-binary" tabindex="-1">Download Binary <a class="header-anchor" href="#download-binary" aria-label="Permalink to &quot;Download Binary&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Folgen Sie zunächst der Anleitung <a href="./myfirstdevice">Mein erstes Gerät</a> und erstellen Sie eine Konfigurationsdatei. Anschließend generieren Sie die Binärdatei und laden sie herunter:</p></div><img src="'+r+'" width="60%" height="60%" align="center"><h2 id="binary-hochladen" tabindex="-1">Binary hochladen <a class="header-anchor" href="#binary-hochladen" aria-label="Permalink to &quot;Binary hochladen&quot;">​</a></h2><p>Um das Binary hochzuladen, navigieren Sie zur Tasmota/ESPEasy-Weboberfläche</p><h3 id="tasmota" tabindex="-1">Tasmota <a class="header-anchor" href="#tasmota" aria-label="Permalink to &quot;Tasmota&quot;">​</a></h3><p>Gehen Sie in den Bereich &quot;Firmware-Upgrade&quot;.</p><img src="'+s+'" width="60%" height="60%" align="center"><p>Wählen Sie im Abschnitt &quot;Upgrade per Datei-Upload&quot; die zuvor heruntergeladene Binärdatei</p><img src="'+o+'" width="60%" height="60%" align="center"><p>Wenn alles erfolgreich war, sehen Sie die Meldung &quot;Upload Successful&quot; und ESPHome wird sich mit dem WiFi-Netzwerk verbinden, das in Ihrer .yaml-Datei konfiguriert ist. 🎉</p><img src="'+d+'" width="60%" height="60%" align="center"><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Wenn Sie die Plattform <code>esp8266_pwm output &lt;/components/output/esp8266_pwm&gt;</code> verwenden und von Tasmota wechseln, müssen Sie das Gerät einmal ausschalten. Danach funktioniert die Dimmfunktionalität wie gewohnt und es sind keine weiteren Stromzyklen erforderlich.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Wenn Sie Tasmota 8+ verwenden und nach dem Hochladen der Firmware einen Fehler erhalten, gehen Sie in die Konsole und geben Sie <code>SetOption78 1</code> ein, dann starten Sie das Gerät neu und versuchen die Firmware erneut.</p></div><h3 id="espeasy" tabindex="-1">ESPEasy <a class="header-anchor" href="#espeasy" aria-label="Permalink to &quot;ESPEasy&quot;">​</a></h3><p>Gehen Sie in den Bereich &quot;Tools &quot;.</p><img src="'+l+'" width="60%" height="60%"><p>Drücken Sie unter &quot;Firmware&quot; auf &quot;Load&quot;, wählen Sie dann das zuvor heruntergeladene Binary aus und laden Sie die Binärdatei. Wenn alles erfolgreich war, sollten Sie nun ESPHome auf Ihrem Knoten haben 🎉.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Mit ESPHome müssen Sie sich in den meisten Fällen keine Gedanken über die verfügbare Flash-Größe machen, da die Binärdatei immer nur den Code enthält, den Sie tatsächlich verwenden.</p></div>',21)])])}const f=a(c,[["render",h]]);export{b as __pageData,f as default};
